'use client';

// Vendored from MerchFlow Charts components/web/Scorecard.tsx (commit in lib/merch-flow-report/VENDORED.md).
// Generated by scripts/sync-merch-flow-report.mjs; edit the PATCHES there, not this file.

import { gms } from '@/lib/merch-flow-report/brand/tokens';
import { units, percent } from '@/lib/merch-flow-report/format';
import type { Product } from '@/lib/merch-flow-report/report/types';
import { scorecard, rollUpTail, CATEGORY_COLORS, categoryOf } from '@/lib/merch-flow-report/report/derive';

/**
 * One ranked product list: units, share of gross, rank shift and ratio.
 *
 * Replaces the separate Ratios and Percent views, which differed only in sort
 * order. The long tail collapses into a single row so the page is not 28
 * near-identical slivers.
 */
export function Scorecard({
  products,
  attendance,
  tailThreshold,
  imageUrls,
  onSelect,
}: {
  products: Product[];
  attendance: number;
  tailThreshold: number;
  imageUrls: Record<string, string>;
  onSelect: (product: Product) => void;
}) {
  const rows = scorecard(products);
  const { head, tail, tailUnits, tailShare } = rollUpTail(rows, tailThreshold);

  const maxUnits = Math.max(...rows.map((r) => r.unitsSold), 1);
  const maxShare = Math.max(...rows.map((r) => r.shareOfGross), 0.0001);

  return (
    <div>
      <p className="mb-4 text-[12px]" style={{ color: gms.slate }}>
        Ranked by units sold. The red bar is units, the grey bar is share of tour
        gross. ▲ and ▼ show how far the product ranks higher or lower by share of
        gross than by units. Products under {percent(tailThreshold, 0)} of gross are
        grouped on the last row.
      </p>

      <ul className="divide-y" style={{ borderColor: '#F0F0F0' }}>
        {head.map((row) => {
          const category = row.category ?? categoryOf(row);
          return (
            <li key={row.sku} style={{ borderColor: '#F0F0F0' }}>
              <button
                onClick={() => onSelect(row)}
                className="flex w-full items-center gap-2.5 py-2 text-left sm:gap-4"
              >
                <span className="tnum w-5 shrink-0 text-[11px]" style={{ color: gms.mist }}>
                  {row.rankByUnits}
                </span>

                <span
                  className="hidden h-10 w-10 shrink-0 items-center justify-center overflow-hidden rounded border bg-white sm:flex"
                  style={{ borderColor: gms.border }}
                >
                  {imageUrls[row.sku] ? (
                    /* eslint-disable-next-line @next/next/no-img-element */
                    <img
                      src={imageUrls[row.sku]}
                      alt=""
                      className="max-h-full max-w-full object-contain"
                    />
                  ) : (
                    <span className="text-[7px] uppercase" style={{ color: gms.mist }}>
                      No image
                    </span>
                  )}
                </span>

                <span className="min-w-0 flex-1">
                  <span className="flex items-baseline gap-2">
                    <span className="truncate text-[12.5px] font-semibold">
                      {row.displayName ?? row.name}
                    </span>
                    {row.rankShift !== 0 && (
                      <span
                        className="tnum shrink-0 text-[10px] font-bold"
                        style={{ color: row.rankShift > 0 ? gms.red : gms.mist }}
                        title={`#${row.rankByUnits} by units, #${row.rankByGross} by share of gross`}
                      >
                        {row.rankShift > 0 ? '▲' : '▼'}
                        {Math.abs(row.rankShift)}
                      </span>
                    )}
                  </span>

                  <span className="mt-0.5 flex items-center gap-1.5 text-[10px]" style={{ color: gms.mist }}>
                    <span
                      className="inline-block h-2 w-2 rounded-[2px]"
                      style={{ background: CATEGORY_COLORS[category] }}
                    />
                    {category}
                    <span className="tnum hidden sm:inline">· {row.sku}</span>
                  </span>

                  <span className="mt-1.5 block">
                    <span
                      className="block h-[3px] rounded-full"
                      style={{
                        width: `${Math.max((row.unitsSold / maxUnits) * 100, 1.5)}%`,
                        background: gms.red,
                      }}
                    />
                    <span
                      className="mt-[3px] block h-[3px] rounded-full"
                      style={{
                        width: `${Math.max((row.shareOfGross / maxShare) * 100, 1.5)}%`,
                        background: '#C9CCD1',
                      }}
                    />
                  </span>
                </span>

                <span className="shrink-0 text-right">
                  <span className="tnum block text-[12.5px] font-bold">
                    {units(row.unitsSold)}
                  </span>
                  <span className="tnum block text-[10.5px]" style={{ color: gms.slate }}>
                    {percent(row.shareOfGross)}
                  </span>
                  {attendance > 0 && (
                    <span className="tnum block text-[10px]" style={{ color: gms.mist }}>
                      Ratio 1 in {Math.round(attendance / row.unitsSold).toLocaleString('en-US')}
                    </span>
                  )}
                </span>
              </button>
            </li>
          );
        })}

        {tail.length > 0 && (
          <li
            className="flex items-center gap-2.5 py-2.5 sm:gap-4"
            style={{ borderColor: '#F0F0F0' }}
          >
            <span className="w-5 shrink-0" />
            <span className="hidden h-10 w-10 shrink-0 sm:block" />
            <span className="min-w-0 flex-1 text-[12px]" style={{ color: gms.slate }}>
              {tail.length} more products, each under {percent(tailThreshold, 0)} of gross
            </span>
            <span className="shrink-0 text-right">
              <span className="tnum block text-[12.5px] font-bold" style={{ color: gms.slate }}>
                {units(tailUnits)}
              </span>
              <span className="tnum block text-[10.5px]" style={{ color: gms.mist }}>
                {percent(tailShare)}
              </span>
            </span>
          </li>
        )}
      </ul>
    </div>
  );
}
